<script setup lang="ts">definePageMeta({middleware:'auth'});const {request}=useApi();const search=ref('');const {data,pending,error}=await useAsyncData('customers',()=>request<{data:any[]}>('/customers'),{watch:[search]});</script><template><section><h1 class="text-2xl font-bold mb-4">Customers</h1><input v-model="search" placeholder="Search customers" class="border p-2 rounded mb-4"><p v-if="pending">Loading…</p><p v-else-if="error">Failed to load customers.</p><table v-else class="w-full bg-white"><tr><th>Name</th><th>Address</th><th>Phone</th><th>Email</th></tr><tr v-for="c in data?.data.filter(x=>x.customer_name.toLowerCase().includes(search.toLowerCase()))" :key="c.id"><td>{{c.customer_name}}</td><td>{{c.customer_address}}</td><td>{{c.phone}}</td><td>{{c.email}}</td></tr></table></section></template>
